import {chromium,expect} from '@playwright/test';
import {spawn} from 'node:child_process';
import {createCipheriv,createHash} from 'node:crypto';
import {inflateSync} from 'node:zlib';

const base='http://127.0.0.1:5190';
const server=spawn(process.execPath,['node_modules/vite/bin/vite.js','--host','127.0.0.1','--port','5190','--strictPort'],{stdio:'ignore'});
// Two full-color frames, 80/170ms, infinite loop; generated by Pillow.
const fixtures={
  gif:'R0lGODlhGAAYAIEAAP8AAAAAAAAAAAAAACH/C05FVFNDQVBFMi4wAwEAAAAh+QQACAAAACwAAAAAGAAYAAAIKQABCBxIsKDBgwgTKlzIsKHDhxAjSpxIsaLFixgzatzIsaPHjyBDPgwIACH5BAERAAEALAAAAAAYABgAgQAA/wAAAAAAAAAAAAgpAAEIHEiwoMGDCBMqXMiwocOHECNKnEixosWLGDNq3Mixo8ePIEM+DAgAOw==',
  webp:'',
};
const key=Buffer.alloc(32,1),nonce=Buffer.alloc(12,2);
let browser;
async function fixture(format,reducedMotion='no-preference'){
  const cipher=createCipheriv('aes-256-gcm',key,nonce);
  const encrypted=Buffer.concat([nonce,cipher.update(Buffer.from(fixtures[format],'base64')),cipher.final(),cipher.getAuthTag()]);
  const sha=createHash('sha256').update(encrypted).digest('hex');
  const model={id:'animated',title:'Turntable',style:'Realism',artist_category:'Artists',artist_name:'Artist',media_title:'World',files:[],images:[{key:'animated/'+format,sha256:sha,role:'main',width:24,height:24}]};
  const page=await browser.newPage({viewport:{width:1440,height:1000},reducedMotion});
  const errors=[];page.on('pageerror',e=>errors.push(e.message));
  await page.addInitScript(()=>sessionStorage.setItem('my5tb-age','yes'));
  await page.route('**/api/models?*',r=>r.fulfill({json:{items:[model],total:1,page:1,limit:15}}));
  await page.route('**/api/models/animated',r=>r.fulfill({json:model}));
  await page.route('**/api/facets',r=>r.fulfill({json:{artist_name:['Artist'],media_title:['World'],format:[]}}));
  await page.route('**/api/preview-key',r=>r.fulfill({json:{key:key.toString('base64')}}));
  await page.route('**/api/assets/**',r=>r.fulfill({body:encrypted,contentType:'application/octet-stream'}));
  await page.route('https://fonts.**',r=>r.abort());
  await page.goto(base,{waitUntil:'domcontentloaded'});
  await page.locator('.card-open').scrollIntoViewIfNeeded();
  await expect(page.locator('.card-visual img')).toHaveJSProperty('naturalWidth',24);
  return {page,errors};
}
async function colors(locator){
  const box=await locator.boundingBox(),samples=new Set();
  for(let i=0;i<10;i++){
    const png=await locator.page().screenshot({clip:{x:Math.floor(box.x+box.width/2),y:Math.floor(box.y+box.height/2),width:1,height:1}});
    const data=[];
    for(let offset=8;offset<png.length;){const size=png.readUInt32BE(offset),type=png.toString('ascii',offset+4,offset+8);if(type==='IDAT')data.push(png.subarray(offset+8,offset+8+size));offset+=size+12}
    const pixel=inflateSync(Buffer.concat(data));samples.add(pixel[3]>pixel[1]?'blue':'red');
    await new Promise(resolve=>setTimeout(resolve,45));
  }
  return [...samples].sort();
}
try{
  let ready=false;for(let i=0;i<60;i++){try{ready=(await fetch(base)).ok;if(ready)break}catch{}await new Promise(r=>setTimeout(r,100))}
  if(!ready)throw new Error('Vite unavailable');
  browser=await chromium.launch({channel:'msedge',headless:true});
  for(const format of ['webp','gif']){
    const {page,errors}=await fixture(format),image=page.locator('.card-visual img');
    expect(await colors(image)).toEqual(['blue','red']);
    const animated=await image.getAttribute('src');
    const before=await page.locator('.card-visual').boundingBox();
    await expect(page.locator('#preview-motion')).toHaveCount(0);
    await page.locator('.card-open').click();
    await expect(page.locator('#detail-image')).toHaveAttribute('alt','Turntable preview 1 of 1');
    await expect(page.locator('#gallery-motion')).toHaveCount(0);
    expect(await colors(page.locator('#detail-image'))).toEqual(['blue','red']);
    await page.emulateMedia({reducedMotion:'reduce'});
    await expect(page.locator('#gallery-motion')).toHaveCount(0);
    expect((await colors(page.locator('#detail-image'))).length).toBe(1);
    await page.locator('#close-detail').click();
    const after=await page.locator('.card-visual').boundingBox();
    expect(after.width).toBe(before.width);expect(after.height).toBe(before.height);
    expect(errors).toEqual([]);await page.close();
    console.log('PASS encrypted',format,'animation, pause/play, gallery, live reduced motion and fixed geometry');
  }
  const {page,errors}=await fixture('webp','reduce');
  expect((await colors(page.locator('.card-visual img'))).length).toBe(1);
  await expect(page.locator('#preview-motion')).toHaveCount(0);
  expect(errors).toEqual([]);await page.close();console.log('PASS initial reduced-motion static poster');
}finally{await browser?.close();server.kill()}
